"""Submission accounts: native grants, monitored DSNs, revocation and tombstones."""
from common import *
user='apps-'+uuid.uuid4().hex[:8]+'@oxymot.fr';other='author-'+uuid.uuid4().hex[:8]+'@oxymot.fr';passwords[user]='Mailbox-'+uuid.uuid4().hex;box=cli('mailbox','create',user,password=passwords[user],mutate=True)['data'];cli('alias','create',other,opts=['--mailbox',box['id']],mutate=True)
for name,grant in [('ghost',user),('oxymotion',other)]:
 passwords[name]='App-'+uuid.uuid4().hex;cli('account','password',name,password=passwords[name],mutate=True);cli('account','update',name,opts=['--envelope-from',grant,'--header-from',grant,'--dsn-mailbox',user],mutate=True)
 tag='account-'+uuid.uuid4().hex;sent=probe(action='submit',auth=name,sender=grant,recipient=user,tag=tag);assert sent.get('data_code')==250;wait_read(user,tag);assert not probe(action='imap',user=name)['ok'];check(name+'-cli-password-grants-native-submit-no-imap',sent)
wrong=probe(action='submit',auth='ghost',sender=other,recipient=user,tag='wrong-'+uuid.uuid4().hex);assert wrong.get('mail_code',wrong.get('smtp_code',0))>=500
wrong=probe(action='submit',auth='ghost',sender=user,header=other,recipient=user,tag='wrong-header-'+uuid.uuid4().hex);assert wrong.get('data_code',wrong.get('smtp_code',0))>=500;check('envelope-and-header-isolation',{'envelope_rejected':True,'header_rejected':True})
cli('mailbox','disable',user,opts=['--scope','receive'],mutate=True);blocked=probe(action='submit',auth='ghost',sender=user,recipient='second@oxymot.fr',tag='dsn-blocked');assert 400<=blocked.get('mail_code',blocked.get('smtp_code',0))<500;check('dsn-destination-disabled-health-refusal',blocked)
cli('mailbox','enable',user,opts=['--scope','receive'],mutate=True)
aux='aux'+uuid.uuid4().hex[:8];passwords[aux]='Auxiliary-'+uuid.uuid4().hex;r=cli('account','create',aux,opts=['--envelope-from',other,'--header-from',other,'--dsn-mailbox',user],password=passwords[aux],mutate=True);assert not r['data']['enabled'];assert not probe(action='submit',auth=aux,sender=other,recipient=user,tag='disabled')['ok'];cli('account','enable',aux,mutate=True);assert probe(action='submit',auth=aux,sender=other,recipient=user,tag='enabled-'+uuid.uuid4().hex).get('data_code')==250
cli('account','disable',aux,mutate=True);before=state['revision'];r=cli('account','disable',aux,mutate=True);assert not r['changed'] and state['revision']==before;cli('account','delete',aux,mutate=True);cli('account','create',aux,opts=['--envelope-from',other,'--header-from',other,'--dsn-mailbox',user],password=passwords[aux],mutate=True,expected='MAIL_ADDRESS_CONFLICT');check('account-default-disable-enable-noop-delete-reserved-id',{'id':aux,'reserved':True})
cli('alias','update',other,opts=['--receive','false'],mutate=True);assert probe(action='rcpt',recipient=other)['rcpt_code']==550;cli('alias','update',other,opts=['--receive','true','--mailbox',box['id']],mutate=True);assert probe(action='rcpt',recipient=other)['rcpt_code']==250;cli('alias','delete',other,mutate=True);assert probe(action='rcpt',recipient=other)['rcpt_code']==550;assert not cli('account','show','oxymotion')['data']['enabled'];check('alias-update-delete-atomically-retires-account-grants',{'old_rcpt':550,'oxymotion_disabled':True})
for family in ('mailbox','alias','account'):
 data=cli(family,'list',opts=['--limit','1'])['data'];assert len(data['items'])<=1
 if data['next_cursor']:cli(family,'list',opts=['--limit','1','--cursor',data['next_cursor']])
check('all-list-families-and-pagination',{'snapshot_revision':state['revision']})
destination='repoint-'+uuid.uuid4().hex[:8]+'@oxymot.fr';repoint='route-'+uuid.uuid4().hex[:8]+'@oxymot.fr';passwords[destination]='Destination-'+uuid.uuid4().hex;target=cli('mailbox','create',destination,password=passwords[destination],mutate=True)['data'];cli('alias','create',repoint,opts=['--mailbox',box['id']],mutate=True);cli('account','update','ghost',opts=['--envelope-from',repoint,'--header-from',repoint,'--dsn-mailbox',user],mutate=True)
changed=cli('alias','update',repoint,opts=['--mailbox',target['id']],mutate=True);assert changed['data']['old_mailbox_id']==box['id'] and changed['data']['new_mailbox_id']==target['id'];assert not cli('account','show','ghost')['data']['enabled'];tag='repoint-'+uuid.uuid4().hex;assert probe(action='send',recipient=repoint,tag=tag)['data_code']==250;assert wait_read(destination,tag)['matches']==1;assert probe(action='imap',user=user,tag=tag)['matches']==0;check('alias-repoint-revokes-grants-and-delivers-only-to-new-uuid',changed['data'])
result={'status':'PASS_MAIL03_NATIVE_ACCOUNTS','checks':checks,'commands':commands,'last_revision':state['revision']};(root/'mail03-accounts-result.json').write_text(json.dumps(result,indent=2));print(json.dumps({'status':result['status'],'checks':len(checks)}))
